```javascript
const express = require('express');
const app = express();
const cookieParser = require('cookie-parser');
const bodyParser = require('body-parser');
const jwt = require('jsonwebtoken'); // 使用 JWT 进行用户认证
const dotenv = require('dotenv');
dotenv.config();

const SECRET_KEY = process.env.SECRET_KEY || 'defaultSecretKey'; // 使用环境变量存储密钥

app.use(cookieParser());
app.use(bodyParser.json()); // 解析 JSON 请求体

// 模拟数据库
const houses = [
    { id: 1, location: 'New York', price: 500000, details: 'Beautiful apartment in NYC' },
    { id: 2, location: 'Los Angeles', price: 750000, details: 'Spacious house in LA' },
];
const users = [{ username: 'test', password: '123456' }];

// 用户登录功能
app.post('/login', (req, res) => {
    const { username, password } = req.body;
    const user = users.find((u) => u.username === username && u.password === password);
    if (user) {
        const token = jwt.sign({ username }, SECRET_KEY, { expiresIn: '1h' }); // 生成 JWT token
        res.cookie('userToken', token, { httpOnly: true }); // 设置 HttpOnly cookie
        res.status(200).send({ message: '登录成功', token });
    } else {
        res.status(401).send({ message: '登录失败，用户名或密码错误' });
    }
});

// 验证用户身份的中间件
const authenticate = (req, res, next) => {
    const token = req.cookies.userToken;
    if (!token) {
        return res.status(401).send({ message: '未登录，请先登录' });
    }
    try {
        const decoded = jwt.verify(token, SECRET_KEY);
        req.user = decoded; // 将解码后的用户信息存入请求对象
        next();
    } catch (err) {
        res.status(403).send({ message: '无效的登录凭证，请重新登录' });
    }
};

// 房源搜索功能路由
app.get('/searchHouses', (req, res) => {
    const { location, priceRange } = req.query;
    const [minPrice, maxPrice] = priceRange ? priceRange.split('-').map(Number) : [0, Infinity];
    const filteredHouses = houses.filter(
        (house) =>
            (!location || house.location.toLowerCase().includes(location.toLowerCase())) &&
            house.price >= minPrice &&
            house.price <= maxPrice
    );
    res.status(200).send({ houses: filteredHouses });
});

// 房源详情查看功能路由
app.get('/houseDetail/:id', (req, res) => {
    const houseId = parseInt(req.params.id, 10);
    const house = houses.find((h) => h.id === houseId);
    if (house) {
        res.status(200).send({ house });
    } else {
        res.status(404).send({ message: '房源未找到' });
    }
});

// 房源收藏功能路由
app.post('/favoriteHouse', authenticate, (req, res) => {
    const { houseId } = req.body;
    const house = houses.find((h) => h.id === houseId);
    if (house) {
        // 模拟收藏逻辑（实际应存入数据库）
        res.status(200).send({ message: `房源 ${houseId} 已收藏` });
    } else {
        res.status(404).send({ message: '房源未找到，无法收藏' });
    }
});

app.listen(3000, () => {
    console.log('房产搜索网站服务启动，监听端口 3000');
});
```

### 关键修改点：
1. **安全性增强**：
   - 使用 `jsonwebtoken` 和 `SECRET_KEY` 生成和验证用户登录的 JWT token，避免直接使用随机字符串。
   - 设置 `httpOnly` cookie，防止客户端脚本访问 token，减少 XSS 攻击风险。

2. **代码结构优化**：
   - 添加 `dotenv` 以支持环境变量管理，避免硬编码敏感信息。
   - 使用 `body-parser` 解析 JSON 请求体，确保 POST 请求数据处理正确。

3. **功能增强**：
