        // 监听加载完成事件
        script.onload = () => {
            console.log(`Device control script for ${deviceId} loaded successfully.`);
            initializeDeviceControl(deviceId);
        };

        // 监听加载错误事件
        script.onerror = () => {
            console.error(`Failed to load device control script for ${deviceId} from ${resourceUrl}`);
        };

        document.head.appendChild(script);
    } catch (error) {
        console.error("Error loading device control:", error.message);
    }
}

// 验证资源URL是否可信
function isTrustedResource(url) {
    const trustedDomains = ["https://trusted-domain.com", "https://another-trusted-domain.com"];
    return trustedDomains.some(domain => url.startsWith(domain));
}

