```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Medical Records Management</title>
    <!-- 引入 jQuery -->
    <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
    <!-- 引入 Chart.js -->
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        #patient-records {
            margin-bottom: 20px;
        }
        .record {
            margin-bottom: 10px;
        }
        .edit-btn {
            margin-left: 10px;
            cursor: pointer;
            color: blue;
        }
        .save-btn {
            margin-left: 10px;
            cursor: pointer;
            color: green;
        }
    </style>
</head>
<body>
    <div id="patient-records">
        <h1>Medical Records</h1>
        <div id="records-container">
            <!-- 动态加载用户的医疗记录 -->
        </div>
    </div>

    <canvas id="medical-chart" width="400" height="200"></canvas>

    <script>
        $(document).ready(function() {
            // 模拟医疗记录数据
            const medicalRecords = [
                { id: 1, date: "2023-10-01", description: "Routine Checkup", value: 120 },
                { id: 2, date: "2023-10-10", description: "Blood Test", value: 80 },
                { id: 3, date: "2023-10-15", description: "X-Ray", value: 95 }
            ];

            // 加载医疗记录到页面
            function loadRecords() {
                const container = $("#records-container");
                container.empty(); // 清空容器
                medicalRecords.forEach(record => {
                    container.append(`
                        <div class="record" data-id="${record.id}">
                            <span><strong>Date:</strong> ${record.date}</span>
                            <span><strong>Description:</strong> <span class="description">${record.description}</span></span>
                            <span><strong>Value:</strong> <span class="value">${record.value}</span></span>
                            <span class="edit-btn">[Edit]</span>
                        </div>
                    `);
                });
            }

            // 编辑功能
            $(document).on("click", ".edit-btn", function() {
                const recordDiv = $(this).closest(".record");
                const description = recordDiv.find(".description").text();
                const value = recordDiv.find(".value").text();

                // 替换为输入框
                recordDiv.find(".description").html(`<input type="text" class="edit-description" value="${description}">`);
                recordDiv.find(".value").html(`<input type="number" class="edit-value" value="${value}">`);
                $(this).replaceWith('<span class="save-btn">[Save]</span>');
            });

            // 保存功能
            $(document).on("click", ".save-btn", function() {
                const recordDiv = $(this).closest(".record");
                const id = recordDiv.data("id");
                const newDescription = recordDiv.find(".edit-description").val();
                const newValue = recordDiv.find(".edit-value").val();

                // 更新数据
                const record = medicalRecords.find(r => r.id === id);
                if (record) {
                    record.description = newDescription;
                    record.value = parseInt(newValue);
                }

                // 重新加载记录
                loadRecords();
                renderChart(); // 更新图表
            });

            // 渲染图表
            function renderChart() {
                const ctx = document.getElementById('medical-chart').getContext('2d');
                const labels = medicalRecords.map(record => record.date);
                const data = medicalRecords.map(record => record.value);

                if (window.myChart) {
                    window.myChart.destroy(); // 销毁旧图表
                }

                window.myChart = new Chart(ctx, {
                    type: 'line',
                    data: {
                        labels: labels,
                        datasets: [{
                            label: 'Medical Data',
                            data: data,
                            borderColor: 'rgba(75, 192, 192, 1)',
                            backgroundColor: 'rgba(75, 192, 192, 0.2)',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        plugins: {
                            legend: {
                                display: true
                            }
                        },
                        scales: {
                            y: {
                                beginAtZero: true
                            }
                        }
                    }
                });
            }

            // 初始化
            loadRecords();
            renderChart();
        });
