    }
    .post {
      border: 1px solid #ddd;
      padding: 15px;
      margin-bottom: 15px;
      border-radius: 5px;
      background-color: #f9f9f9;
    }
    .post img {
      max-width: 100%;
      height: auto;
      border-radius: 5px;
    }
    .post video {
