```php
<?php
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    session_start();
    require_once 'db_connection.php'; // 假设你有一个单独的数据库连接文件

    $user_id = $_POST['user_id'] ?? null;
    $post_id = $_POST['post_id'] ?? null;
    $post_content = $_POST['content'] ?? null;

    // 验证用户是否已登录
    if (!isset($_SESSION['user_id'])) {
        http_response_code(403);
        echo "Unauthorized access!";
        exit;
    }

    // 验证输入是否为空
    if (empty($user_id) || empty($post_id) || empty($post_content)) {
        http_response_code(400);
        echo "Invalid input!";
        exit;
    }

    // 使用准备语句防止SQL注入
    $stmt = $conn->prepare("SELECT user_id FROM posts WHERE post_id = ?");
    $stmt->bind_param("i", $post_id);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($result->num_rows === 0) {
        http_response_code(404);
        echo "Post not found!";
        exit;
    }

    $post = $result->fetch_assoc();

    // 检查是否是当前用户的帖子
    if ($post['user_id'] != $_SESSION['user_id']) {
        http_response_code(403);
        echo "You cannot edit this post!";
        exit;
    }

    // 更新帖子内容
    $stmt = $conn->prepare("UPDATE posts SET content = ? WHERE post_id = ?");
    $stmt->bind_param("si", $post_content, $post_id);

    if ($stmt->execute()) {
        echo "Post updated successfully!";
    } else {
        http_response_code(500);
        echo "Failed to update post!";
    }

    $stmt->close();
    $conn->close();
}
?>
