    <form method="POST">
        <label for="object_name">物体名称：</label>
        <input type="text" name="object_name" id="object_name" required><br><br>

        <label for="height">下落高度（米）：</label>
        <input type="number" name="height" id="height" step="0.01" min="0.01" required><br><br>

        <input type="submit" value="开始实验">
    </form>

    <h2>历史实验记录</h2>
    <?php
    // 显示最近的实验记录
    $result = $conn->query("SELECT * FROM gravity_experiments ORDER BY created_at DESC LIMIT 5");
    if ($result && $result->num_rows > 0) {
        while ($row = $result->fetch_assoc()) {
            echo "<p><strong>物体名称:</strong> " . htmlspecialchars($row['object_name']) . "<br>";
            echo "<strong>高度:</strong> " . $row['height'] . "米<br>";
            echo "<strong>下落时间:</strong> " . number_format($row['fall_time'], 2) . "秒<br>";
            echo "<strong>实验时间:</strong> " . $row['created_at'] . "</p><hr>";
        }
    } else {
        echo "<p>没有实验记录。</p>";
    }
    ?>
</body>
</html>
```

