               $message .= "<li><strong>$safeSymptom:</strong> " . htmlspecialchars($diagnoses[$safeSymptom], ENT_QUOTES, 'UTF-8') . "</li>";
           }
       }
       $message .= '</ul>';
       return $message;
   }

