        // 验证链接被正确渲染
        $this->assertEquals("这是一个包含链接的评论 <a href=\"http://example.com\">点击我</a>", $result);
    }

    public function testRenderCommentWithImage() {
        // 创建一条包含图片的评论
        $comment = new Comment('comment4', '这是一个包含图片的评论 <img src="http://example.com/image.jpg" alt="图片">');
