```php
<?php
class SecureTransfer {
    private $encryptionKey;
    private $cipherMethod;

    public function __construct($key) {
        // 设置加密密钥和加密方法
        $this->encryptionKey = hash('sha256', $key, true); // 确保密钥长度为256位
        $this->cipherMethod = 'AES-256-CBC';
    }

    /**
     * 加密数据
     * @param string $data 要加密的明文数据
     * @return string 加密后的数据（包含IV）
     */
    public function encrypt($data) {
        $ivLength = openssl_cipher_iv_length($this->cipherMethod);
        $iv = openssl_random_pseudo_bytes($ivLength); // 生成随机IV
        $encryptedData = openssl_encrypt($data, $this->cipherMethod, $this->encryptionKey, 0, $iv);

        if ($encryptedData === false) {
            throw new Exception('Encryption failed.');
        }

        // 将IV和加密数据组合后返回（使用 base64 编码）
        return base64_encode($iv . $encryptedData);
    }

    /**
     * 解密数据
     * @param string $encryptedData 加密后的数据（包含IV）
     * @return string 解密后的明文数据
     */
    public function decrypt($encryptedData) {
        $data = base64_decode($encryptedData);
        $ivLength = openssl_cipher_iv_length($this->cipherMethod);
        $iv = substr($data, 0, $ivLength); // 提取IV
        $cipherText = substr($data, $ivLength); // 提取加密数据

        $decryptedData = openssl_decrypt($cipherText, $this->cipherMethod, $this->encryptionKey, 0, $iv);

        if ($decryptedData === false) {
            throw new Exception('Decryption failed.');
        }

        return $decryptedData;
    }
}

// 示例用法
