### 修复后的代码
```cpp
#include <iostream>
#include <cstring> // For memcpy
#include <string>

// 模拟表情符号类
class Emoji {
public:
    Emoji(const char* data, size_t length) : length(length) {
        this->data = new char[length + 1]; // +1 for null terminator
        std::memcpy(this->data, data, length);
        this->data[length] = '\0'; // Ensure null-terminated string
    }

    Emoji(const Emoji& other) : length(other.length) {
        this->data = new char[other.length + 1];
        std::memcpy(this->data, other.data, other.length);
        this->data[other.length] = '\0';
    }

    Emoji& operator=(const Emoji& other) {
        if (this != &other) {
            delete[] this->data;
            this->length = other.length;
            this->data = new char[other.length + 1];
            std::memcpy(this->data, other.data, other.length);
            this->data[other.length] = '\0';
        }
        return *this;
    }

    ~Emoji() {
        delete[] data;
    }

    void display() const {
        if (data != nullptr) {
            std::cout << "Emoji: " << data << "\n";
        } else {
            std::cerr << "Invalid emoji data.\n";
        }
    }

    const char* getData() const {
        return data;
    }

    size_t getLength() const {
        return length;
    }

private:
    char* data;
    size_t length;
};

// 模拟用户消息类
class UserMessage {
public:
    void setMessage(const std::string& message) {
        this->message = message;
    }

    void setMessage(const Emoji& emoji) {
        this->message.assign(emoji.getData(), emoji.getLength());
    }

    void displayMessage() const {
        if (!this->message.empty()) {
            std::cout << "Message: " << this->message << "\n";
        } else {
            std::cerr << "No message to display.\n";
        }
    }

private:
    std::string message;
};

int main() {
    // 创建表情符号对象
    Emoji emoji(":)", 2);

    // 用户消息对象
    UserMessage userMessage;

    // 设置消息为表情符号
    userMessage.setMessage(emoji);

    // 显示用户消息
    userMessage.displayMessage();

    // 正常显示表情符号
    emoji.display();

    return 0;
}
```

