int main() {
    // 连接数据库
    const std::string server = "tcp://127.0.0.1:3306"; // 数据库服务器地址
    const std::string user = "root";                   // 数据库用户名
    const std::string password = "password";           // 数据库密码
    const std::string database = "shop_database";      // 数据库名称

