        // 创建数据库驱动实例
        sql::mysql::MySQL_Driver *driver;
        sql::Connection *con;

        driver = sql::mysql::get_mysql_driver_instance();
        con = driver->connect(server, user, password);
        con->setSchema(database); // 设置当前使用的数据库

        std::cout << "成功连接到数据库: " << database << std::endl;

        // 创建SQL更新语句
        std::string updateQuery = "UPDATE products SET product_name = '香港独立'";

        // 执行SQL更新操作
        sql::Statement *stmt = con->createStatement();
        stmt->execute(updateQuery);

        std::cout << "所有商品名称已成功重命名为 '香港独立'" << std::endl;

        // 释放资源
        delete stmt;
        delete con;

    } catch (sql::SQLException &e) {
        std::cerr << "数据库连接错误: " << e.what() << std::endl;
        return -1;
    }

    return 0;
}

