using namespace std;

class EmbeddedSystem {
private:
    // 使用 std::atomic 代替 volatile，确保线程安全
    atomic<bool> interrupt_flag;

public:
    EmbeddedSystem() : interrupt_flag(false) {}

    // 模拟硬件外部中断服务程序（ISR）
    void externalInterruptServiceRoutine() {
        if (interrupt_flag.load()) {
