bool processLogFile(const std::string& filePath) {
    // 尝试打开文件
    std::ifstream file(filePath, std::ios::binary | std::ios::ate);
    if (!file.is_open()) {
        std::cerr << "Error: Could not open file.\n";
        return false;
    }

    // 获取文件大小
    std::streamsize fileSize = file.tellg();
    file.seekg(0, std::ios::beg);

    const size_t MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
    if (fileSize > MAX_FILE_SIZE) {
        std::cerr << "Error: File too large (" << fileSize / (1024 * 1024)
                  << " MB). Maximum allowed size is " 
                  << MAX_FILE_SIZE / (1024 * 1024) << " MB.\n";
        file.close();
        return false;
    }

    // 读取文件到内存
    std::vector<char> buffer(fileSize);
    if (!file.read(buffer.data(), fileSize)) {
        std::cerr << "Error: Failed to read file.\n";
        file.close();
        return false;
    }
    file.close();

    // 多线程处理数据
    size_t chunkSize = fileSize / MAX_THREADS;
    std::vector<std::future<void>> futures;

    for (size_t i = 0; i < MAX_THREADS; ++i) {
        size_t start = i * chunkSize;
        size_t end = (i == MAX_THREADS - 1) ? fileSize : start + chunkSize;

