// 生成随机盐
std::string generate_salt(size_t length = 16) {
    unsigned char salt[length];
    RAND_bytes(salt, length);
    std::stringstream ss;
    for (size_t i = 0; i < length; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)salt[i];
    }
    return ss.str();
}

// 使用 PBKDF2 进行加盐哈希
std::string hash_password(const std::string& password, const std::string& salt, int iterations = 10000, int key_length = 32) {
    unsigned char hash[key_length];
    PKCS5_PBKDF2_HMAC(password.c_str(), password.size(),
                      reinterpret_cast<const unsigned char*>(salt.c_str()), salt.size(),
                      iterations, EVP_sha256(), key_length, hash);

    std::stringstream ss;
    for (int i = 0; i < key_length; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

