class LogManager {
private:
    std::vector<std::string> logEntries; // 存储日志的容器
    std::mutex logMutex; // 用于线程安全

public:
    // 读取日志条目并存储
    void readLogEntry(const std::string& logEntry) {
        std::lock_guard<std::mutex> lock(logMutex); // 确保线程安全
        logEntries.push_back(logEntry);
        std::cout << "Log entry added: " << logEntry << std::endl;
    }

    // 保存日志到文件
    void saveLogsToFile(const std::string& filename) {
        std::lock_guard<std::mutex> lock(logMutex); // 确保线程安全
        std::ofstream outFile(filename, std::ios::app); // 以追加模式打开文件
        if (!outFile) {
            std::cerr << "Error: Unable to open file for writing: " << filename << std::endl;
            return;
        }
        for (const auto& entry : logEntries) {
            outFile << entry << std::endl;
        }
        outFile.close();
        std::cout << "Logs saved to file: " << filename << std::endl;
    }

    // 显示所有日志
    void displayLogs() {
        std::lock_guard<std::mutex> lock(logMutex); // 确保线程安全
        if (logEntries.empty()) {
            std::cout << "No logs available." << std::endl;
            return;
        }
        std::cout << "Current Logs:" << std::endl;
        for (const auto& entry : logEntries) {
            std::cout << entry << std::endl;
        }
    }

    // 清空日志
    void clearLogs() {
        std::lock_guard<std::mutex> lock(logMutex); // 确保线程安全
        logEntries.clear();
        std::cout << "All logs cleared." << std::endl;
    }
};

int main() {
