    // 示例操作
    logManager.readLogEntry("System started.");
    logManager.readLogEntry("User logged in.");
    logManager.readLogEntry("Error: Unable to connect to server.");

    logManager.displayLogs();

    logManager.saveLogsToFile("logs.txt");

    logManager.clearLogs();
    logManager.displayLogs();

    return 0;
}
```

