以下是将您的 Python 代码转换为 C++ 的版本。C++ 中没有直接的弱引用机制（如 Python 的 `weakref`），但可以使用 `std::weak_ptr` 来实现类似的功能。以下代码使用了 `std::shared_ptr` 和 `std::weak_ptr` 来管理设备的生命周期。

### 转换后的 C++ 代码
```cpp
#include <iostream>
#include <memory>
#include <unordered_map>
#include <string>

class SmartHomeDevice {
public:
    SmartHomeDevice(const std::string& device_id, const std::string& name)
        : device_id_(device_id), name_(name) {
        std::cout << "Device " << name_ << " created." << std::endl;
    }

    ~SmartHomeDevice() {
        std::cout << "Device " << name_ << " destroyed." << std::endl;
    }

    const std::string& getName() const {
        return name_;
    }

private:
    std::string device_id_;
    std::string name_;
};

class SmartHomeController {
public:
    void addDevice(const std::string& device_id, const std::string& name) {
        auto device = std::make_shared<SmartHomeDevice>(device_id, name);
        devices_[device_id] = device;  // Strong reference
        weak_devices_[device_id] = device;  // Weak reference
    }

    void removeDevice(const std::string& device_id) {
        auto it = devices_.find(device_id);
        if (it != devices_.end()) {
            devices_.erase(it);  // Remove strong reference
            std::cout << "Device " << device_id << " removed." << std::endl;
        } else {
            std::cout << "Device not found." << std::endl;
        }
    }

    void controlDevice(const std::string& device_id, const std::string& command) {
        auto it = devices_.find(device_id);
        if (it != devices_.end()) {
            std::cout << "Controlling device " << it->second->getName()
                      << " with command: " << command << "." << std::endl;
        } else {
            std::cout << "Device not found." << std::endl;
        }
    }

    void checkWeakReference(const std::string& device_id) {
        auto it = weak_devices_.find(device_id);
        if (it != weak_devices_.end()) {
            if (auto device = it->second.lock()) {  // Check if weak_ptr is still valid
                std::cout << "Weak reference to device " << device_id << " still exists." << std::endl;
            } else {
                std::cout << "Weak reference to device " << device_id << " has been garbage collected." << std::endl;
            }
        } else {
            std::cout << "Device not found in weak references." << std::endl;
        }
    }

private:
    std::unordered_map<std::string, std::shared_ptr<SmartHomeDevice>> devices_;  // Strong references
    std::unordered_map<std::string, std::weak_ptr<SmartHomeDevice>> weak_devices_;  // Weak references
};

int main() {
    SmartHomeController controller;

    // Add devices
    controller.addDevice("light1", "Living Room Light");
    controller.addDevice("thermostat", "Smart Thermostat");

    // Control devices
    controller.controlDevice("light1", "turn on");

    // Remove a device
    controller.removeDevice("light1");

    // Try to control a removed device
    controller.controlDevice("light1", "turn off");

    // Check weak reference
    controller.checkWeakReference("light1");

    return 0;
}
```

### 关键修改点
1. **内存管理**：
   - 使用 `std::shared_ptr` 替代 Python 的强引用。
   - 使用 `std::weak_ptr` 替代 Python 的 `weakref.WeakValueDictionary`，以实现弱引用。

2. **设备管理**：
   - 使用 `std::unordered_map` 替代 Python 的字典来存储设备。

3. **弱引用检查**：
   - 使用 `std::weak_ptr::lock()` 检查弱引用是否仍然有效。

4. **析构函数**：
