const std::string base_url = "http://yourserver.com/embed_player";

// 构造不同的来源域名用于测试
std::vector<std::string> test_domains = {
    "trusted-source.com",  // 可信来源
    "untrusted-source.com", // 不可信来源
    "malicious-site.com"   // 恶意网站
};

// 用于存储HTTP响应头
std::map<std::string, std::string> response_headers;

// 回调函数，用于处理HTTP响应头
size_t HeaderCallback(char* buffer, size_t size, size_t nitems, void* userdata) {
    size_t total_size = size * nitems;
    std::string header(buffer, total_size);
    size_t colon_pos = header.find(':');
    if (colon_pos != std::string::npos) {
        std::string key = header.substr(0, colon_pos);
        std::string value = header.substr(colon_pos + 1);
        // 去掉多余的空格
        key.erase(key.find_last_not_of(" \t\n\r") + 1);
        value.erase(0, value.find_first_not_of(" \t\n\r"));
        response_headers[key] = value;
    }
    return total_size;
}

// 检查CSP头部信息
std::string check_csp_headers() {
    auto it = response_headers.find("Content-Security-Policy");
    if (it != response_headers.end()) {
        std::string csp_header = it->second;
        std::cout << "CSP Header found: " << csp_header << std::endl;

        size_t pos = csp_header.find("frame-ancestors");
        if (pos != std::string::npos) {
            size_t end_pos = csp_header.find(';', pos);
            std::string frame_ancestors = csp_header.substr(pos, end_pos - pos);
            std::cout << "Frame-Ancestors Directive: " << frame_ancestors << std::endl;
            return frame_ancestors;
        }
    }
    std::cout << "No Frame-Ancestors Directive found." << std::endl;
    return "";
}

// 测试嵌入域名
void test_embed_from_domain(const std::string& domain, const std::string& referrer) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        std::cerr << "Failed to initialize CURL." << std::endl;
        return;
    }

    response_headers.clear(); // 清空之前的响应头

    struct curl_slist* headers = nullptr;
    if (!referrer.empty()) {
        std::string referer_header = "Referer: http://" + referrer + "/page.html";
        headers = curl_slist_append(headers, referer_header.c_str());
    }

    curl_easy_setopt(curl, CURLOPT_URL, base_url.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, HeaderCallback);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res == CURLE_OK) {
        long response_code;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

        if (response_code == 200) {
            std::cout << "Request from " << domain << " succeeded." << std::endl;

            // 检查CSP头部信息
            std::string csp_directive = check_csp_headers();

            // 尝试加载内容，根据CSP判断是否应该成功
