#include <htmlcxx/html/escape.h> // For HTML escaping

// WebSocket server type
typedef websocketpp::server<websocketpp::config::asio> websocket_server;

// Global variables to store posts and WebSocket connections
std::vector<std::string> posts;
std::vector<websocketpp::connection_hdl> connections;
std::mutex connection_mutex;

// HTML template for a post
const std::string POST_TEMPLATE = R"(
<div class="post">
    <p>{content}</p>
</div>
)";

// Function to escape HTML to prevent XSS
std::string escape_html(const std::string& input) {
    return htmlcxx::html::escape(input);
}

// Function to replace {content} in the template with the actual post content
std::string render_post(const std::string& content) {
    std::string escaped_content = escape_html(content);
    std::string rendered = POST_TEMPLATE;
    size_t pos = rendered.find("{content}");
    if (pos != std::string::npos) {
        rendered.replace(pos, 9, escaped_content);
    }
    return rendered;
}

// WebSocket message handler
void on_message(websocket_server* server, websocketpp::connection_hdl hdl, websocketpp::config::asio::message_type::ptr msg) {
    // Broadcast the message to all connected clients
    std::lock_guard<std::mutex> lock(connection_mutex);
    for (auto& conn : connections) {
        server->send(conn, msg->get_payload(), websocketpp::frame::opcode::text);
    }
}

// WebSocket open handler
void on_open(websocket_server* server, websocketpp::connection_hdl hdl) {
    std::lock_guard<std::mutex> lock(connection_mutex);
    connections.push_back(hdl);

    // Send existing posts to the newly connected client
    for (const auto& post : posts) {
        server->send(hdl, post, websocketpp::frame::opcode::text);
    }
}

// WebSocket close handler
void on_close(websocket_server* server, websocketpp::connection_hdl hdl) {
    std::lock_guard<std::mutex> lock(connection_mutex);
    connections.erase(std::remove(connections.begin(), connections.end(), hdl), connections.end());
}

int main() {
    crow::SimpleApp app;

    // WebSocket server setup
    websocket_server ws_server;
    ws_server.init_asio();

    ws_server.set_message_handler([&ws_server](websocketpp::connection_hdl hdl, websocketpp::config::asio::message_type::ptr msg) {
        on_message(&ws_server, hdl, msg);
    });

    ws_server.set_open_handler([&ws_server](websocketpp::connection_hdl hdl) {
        on_open(&ws_server, hdl);
    });

    ws_server.set_close_handler([&ws_server](websocketpp::connection_hdl hdl) {
        on_close(&ws_server, hdl);
    });

    // Start WebSocket server in a separate thread
    std::thread ws_thread([&ws_server]() {
        ws_server.listen(9002);
        ws_server.start_accept();
        ws_server.run();
    });

    // HTTP route to handle post submissions
    CROW_ROUTE(app, "/submit").methods("POST"_method)([] (const crow::request& req) {
        auto content = req.body;
        std::string rendered_post = render_post(content);

        // Store the post
        {
            std::lock_guard<std::mutex> lock(connection_mutex);
            posts.push_back(rendered_post);
        }

        // Broadcast the new post to all WebSocket clients
        {
            std::lock_guard<std::mutex> lock(connection_mutex);
            for (auto& conn : connections) {
                ws_server.send(conn, rendered_post, websocketpp::frame::opcode::text);
            }
        }

        return "Post submitted";
    });

    // Start the HTTP server
    app.port(8080).multithreaded().run();

    // Join the WebSocket thread before exiting
    ws_thread.join();

    return 0;
}
```

### 说明：
1. **Crow** 用于处理 HTTP 请求（如 `/submit` 路由）。
2. **WebSocket++** 用于处理 WebSocket 通信，支持实时更新。
3. 添加了 `escape_html` 函数，使用 `htmlcxx` 库对用户输入进行 HTML 转义，防止 XSS 攻击。
4. 使用 `std::mutex` 确保多线程环境下对共享资源（如 `posts` 和 `connections`）的安全访问。
5. WebSocket 服务器运行在端口 `9002`，HTTP 服务器运行在端口 `8080`。

### 依赖：
- **Crow**: [https://github.com/CrowCpp/Crow](https://github.com/CrowCpp/Crow)
- **WebSocket++**: [https://github.com/zaphoyd/websocketpp](https://github.com/zaphoyd/websocketpp)
- **htmlcxx**: 用于 HTML 转义。

