```cpp
#include <iostream>
#include <iomanip>
#include <cmath>
#include <stdexcept>
#include <string>

// Function to convert float amount to integer (smallest currency unit)
int convertToCents(const std::string& amountStr) {
    try {
        // Convert string to double
        double amount = std::stod(amountStr);

        // Check for negative values
        if (amount < 0) {
            throw std::invalid_argument("Amount cannot be negative.");
        }

        // Convert to smallest currency unit (e.g., cents) with rounding
        int cents = static_cast<int>(std::round(amount * 100));

        return cents;
    } catch (const std::invalid_argument& e) {
        throw std::invalid_argument("Invalid input: " + amountStr);
    } catch (const std::out_of_range& e) {
        throw std::out_of_range("Input value is out of range.");
    }
}

int main() {
