// 2. 提前过滤不符合类别的课程，减少不必要的循环。
func searchCourses(courses []Course, category, keyword string) []Course {
	var results []Course
	keyword = strings.ToLower(keyword) // 统一转为小写，支持大小写不敏感搜索
	for _, course := range courses {
		if strings.ToLower(course.Category) == strings.ToLower(category) { // 类别匹配
			if _, exists := course.Keywords[keyword]; exists { // 关键词匹配
				results = append(results, course)
			}
		}
	}
	return results
}

func main() {
	// 初始化课程数据，使用map[string]struct{}存储关键词
	courses := []Course{
		{"Go Programming", "Technology", toKeywordMap([]string{"Go", "Programming", "Beginner"})},
		{"Python Basics", "Technology", toKeywordMap([]string{"Python", "Programming", "Beginner"})},
		{"Advanced Yoga", "Health", toKeywordMap([]string{"Yoga", "Health", "Advanced"})},
		{"Data Science", "Technology", toKeywordMap([]string{"Data Science", "Programming", "Advanced"})},
	}

	// 搜索课程
	results := searchCourses(courses, "Technology", "Go")
	fmt.Println("Search Results:")
	for _, course := range results {
		fmt.Printf("Title: %s, Category: %s\n", course.Title, course.Category)
	}
}

// toKeywordMap将关键词切片转换为map[string]struct{}，以提高查找效率
func toKeywordMap(keywords []string) map[string]struct{} {
	keywordMap := make(map[string]struct{}, len(keywords))
	for _, keyword := range keywords {
		keywordMap[strings.ToLower(keyword)] = struct{}{} // 转为小写，支持大小写不敏感搜索
	}
	return keywordMap
}
```

### 关键修改点
1. **关键词存储优化**：
   - 将`Keywords`从`[]string`改为`map[string]struct{}`，以便在搜索时可以通过`O(1)`复杂度快速判断关键词是否存在。
   - 使用`toKeywordMap`函数将关键词切片转换为`map[string]struct{}`。

2. **大小写不敏感搜索**：
   - 在类别和关键词比较时，使用`strings.ToLower`将字符串统一转为小写，支持大小写不敏感的搜索。

3. **减少不必要的循环**：
   - 先检查课程类别是否匹配，再检查关键词是否匹配，避免对不符合类别的课程进行多余的关键词查找。

4. **代码可读性改进**：
   - 提取了`toKeywordMap`函数，简化了课程初始化的代码。
   - 在`main`函数中打印搜索结果时，格式化输出，提升可读性。

### 性能提升
- 原代码在关键词匹配时需要遍历整个`Keywords`切片，时间复杂度为`O(n*m*k)`（`n`为课程数，`m`为每门课程的关键词数，`k`为关键词长度）。
- 优化后，关键词匹配通过`map`实现，时间复杂度降为`O(n*k)`，显著提升了性能，尤其在课程和关键词数量较多时效果更明显。

