以下是优化后的代码，主要增强了安全性，防止潜在的安全漏洞（如XSS攻击）和不安全的嵌入内容：

```go
package main

import (
	"fmt"
	"html/template"
	"net/http"
	"net/url"
	"strings"
)

func iframeHandler(w http.ResponseWriter, r *http.Request) {
	iframeURL := r.URL.Query().Get("iframe_url")
	if iframeURL == "" {
		http.Error(w, "iframe URL is missing", http.StatusBadRequest)
		return
	}

	// Validate the iframe URL
	parsedURL, err := url.Parse(iframeURL)
	if err != nil || !parsedURL.IsAbs() || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		http.Error(w, "Invalid iframe URL", http.StatusBadRequest)
		return
	}

	// Prevent embedding untrusted domains
	allowedDomains := []string{"trusted.com", "example.com"}
	isAllowed := false
	for _, domain := range allowedDomains {
		if strings.HasSuffix(parsedURL.Hostname(), domain) {
			isAllowed = true
			break
		}
	}
	if !isAllowed {
		http.Error(w, "Embedding from this domain is not allowed", http.StatusForbidden)
		return
	}

	// Use template to escape the URL properly
	tmpl := template.Must(template.New("iframe").Parse(`
		<!DOCTYPE html>
		<html lang="en">
		<head>
			<meta charset="UTF-8">
			<meta name="viewport" content="width=device-width, initial-scale=1.0">
			<title>Embedded Content</title>
		</head>
		<body>
			<iframe src="{{.}}" width="600" height="400" frameborder="0" allowfullscreen></iframe>
		</body>
		</html>
	`))

	w.Header().Set("Content-Type", "text/html")
	if err := tmpl.Execute(w, iframeURL); err != nil {
		http.Error(w, "Failed to render iframe", http.StatusInternalServerError)
	}
}

func main() {
	http.HandleFunc("/embed", iframeHandler)
	fmt.Println("Server is running on http://localhost:8080")
	http.ListenAndServe(":8080", nil)
}
```

### 关键修改点：
1. **URL 验证**：
   - 使用 `url.Parse` 验证 `iframe_url` 是否是有效的绝对 URL。
   - 限制 URL 的协议为 `http` 或 `https`，防止不安全的协议（如 `javascript:`）。

2. **域名白名单**：
   - 添加了 `allowedDomains` 列表，限制只能嵌入来自可信域名的内容，防止恶意网站的嵌入。

3. **模板渲染**：
   - 使用 `html/template` 渲染 HTML，自动对嵌入的 URL 进行转义，防止 XSS 攻击。

4. **安全的 HTTP 响应头**：
   - 设置 `Content-Type` 为 `text/html`，确保浏览器正确解析内容。

5. **错误处理**：
   - 增加了对模板渲染失败的错误处理，避免程序崩溃。

通过这些改进，代码更加安全，能够有效防止常见的安全问题，如 XSS 和不受信任的内容嵌入。

