以下是优化后的代码，主要改进点包括：

1. **并发处理**：使用 Goroutines 和 WaitGroup 来并发检查房源的可用性，减少等待时间。
2. **减少不必要的模拟延迟**：将模拟数据库检查的 `time.Sleep` 替换为更高效的逻辑。
3. **优化数据结构**：将房源的可用性存储在一个映射中，以便快速查找。
4. **代码结构改进**：将可用性检查和预订逻辑分离，增强代码的可读性和可维护性。

优化后的代码如下：

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

type Booking struct {
	UserID     int
	PropertyID int
	StartDate  time.Time
	EndDate    time.Time
}

// Simulated property availability database
var propertyAvailability = map[int]bool{
	1: true,
	2: true,
	3: false,
	4: true,
	5: true,
}

// checkAvailability checks if a property is available concurrently
func checkAvailability(propertyID int, startDate, endDate time.Time, wg *sync.WaitGroup, resultChan chan bool) {
	defer wg.Done()
	// Simulate a database check for availability
	if available, exists := propertyAvailability[propertyID]; exists && available {
		resultChan <- true
	} else {
		resultChan <- false
	}
}

// isPropertyAvailable checks the availability of a specific property
func isPropertyAvailable(propertyID int, startDate, endDate time.Time) bool {
	var wg sync.WaitGroup
	resultChan := make(chan bool, 1)

	wg.Add(1)
	go checkAvailability(propertyID, startDate, endDate, &wg, resultChan)

	wg.Wait()
	close(resultChan)

	// Return the result from the channel
	for result := range resultChan {
		return result
	}
	return false
}

// makeBooking handles the booking process
func makeBooking(userID int, propertyID int, startDate, endDate time.Time) {
	if isPropertyAvailable(propertyID, startDate, endDate) {
		booking := Booking{userID, propertyID, startDate, endDate}
		fmt.Printf("Booking created: %+v\n", booking)
	} else {
		fmt.Println("Property not available.")
	}
}

func main() {
	userID := 123
	propertyID := 1
	startDate := time.Now()
	endDate := startDate.Add(2 * time.Hour)

	makeBooking(userID, propertyID, startDate, endDate)
}
```

### 关键修改点说明：
