package main

import (
	"fmt"
)

// 假设密码的长度
const passwordLength = 6

// 字符集：可以包含字母和数字
var charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

// 验证密码是否正确的函数
// 假设目标密码为 "abc123"，你可以根据实际情况调整这个目标密码
func isCorrectPassword(password string) bool {
	// 假设密码是 "abc123"
	targetPassword := "abc123"
	return password == targetPassword
}

// 生成所有密码组合并逐一验证
func bruteForce(passwordLength int) string {
	password := make([]byte, passwordLength)
	if findPassword(password, 0, passwordLength) {
		return string(password)
	}
	return ""
}

// 递归函数：逐一生成密码
func findPassword(password []byte, index, length int) bool {
	// 如果生成的密码长度等于指定长度，验证密码
	if index == length {
		return isCorrectPassword(string(password))
	}

	// 循环遍历字符集
	for _, c := range charset {
