```go
package main

import (
	"fmt"
	"sync"
	"time"
)

var (
	lock1 sync.Mutex
	lock2 sync.Mutex
)

func thread1() {
	// 统一按照 lock1 -> lock2 的顺序获取锁
	lock1.Lock()
	fmt.Println("Thread 1: Locked lock1")

	// 模拟一些处理
	time.Sleep(1 * time.Second)

	lock2.Lock()
	fmt.Println("Thread 1: Locked lock2")

	// 释放锁
	lock2.Unlock()
	lock1.Unlock()
}

func thread2() {
	// 统一按照 lock1 -> lock2 的顺序获取锁
	lock1.Lock()
	fmt.Println("Thread 2: Locked lock1")

	// 模拟一些处理
	time.Sleep(1 * time.Second)

	lock2.Lock()
	fmt.Println("Thread 2: Locked lock2")

	// 释放锁
	lock2.Unlock()
	lock1.Unlock()
}

func main() {
	// 启动线程1和线程2
	go thread1()
	go thread2()

	// 等待一段时间，确保程序运行完成
	time.Sleep(3 * time.Second)
}
```

**关键修改点**：
- 统一了锁的获取顺序，`thread1` 和 `thread2` 都按照 `lock1 -> lock2` 的顺序获取锁，避免了死锁的发生。

