```go
package main

import (
	"fmt"
	"net/http"
	"strings"
	"regexp"
)

func handleCommand(w http.ResponseWriter, r *http.Request) {
	// Limit request methods to GET for security
	if r.Method != http.MethodGet {
		http.Error(w, "Invalid request method", http.StatusMethodNotAllowed)
		return
	}

	// Parse query parameters
	deviceID := r.URL.Query().Get("deviceID")
	command := r.URL.Query().Get("command")

	// Validate input parameters
	if deviceID == "" || command == "" {
		http.Error(w, "Missing parameters", http.StatusBadRequest)
		return
	}

	// Sanitize inputs to prevent injection attacks
	if !isValidInput(deviceID) || !isValidInput(command) {
		http.Error(w, "Invalid input parameters", http.StatusBadRequest)
		return
	}

	// Log the command for debugging (optional, avoid logging sensitive data in production)
	fmt.Printf("Received command for device %s: %s\n", deviceID, command)

	// Respond to the client
	fmt.Fprintf(w, "Command received for device %s: %s", deviceID, command)
}

// isValidInput validates input to ensure it only contains alphanumeric characters and basic symbols
func isValidInput(input string) bool {
	// Allow alphanumeric, spaces, dashes, and underscores
	validInputPattern := `^[a-zA-Z0-9_\- ]+$`
	matched, _ := regexp.MatchString(validInputPattern, input)
	return matched
}

func main() {
	// Use a more secure HTTP server configuration
	server := &http.Server{
		Addr: ":8080",
		Handler: http.DefaultServeMux,
	}

	// Register the handler
	http.HandleFunc("/control", handleCommand)

	// Start the server
	fmt.Println("Starting server on :8080")
	if err := server.ListenAndServe(); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}
```

### 关键修改点：
1. **限制HTTP方法**：只允许GET方法，防止其他方法（如POST、PUT）被滥用。
2. **输入验证**：添加`isValidInput`函数，使用正则表达式验证`deviceID`和`command`，确保只包含安全字符，防止注入攻击。
3. **日志记录**：在服务器端打印接收到的命令，便于调试和监控。
4. **更安全的HTTP服务器配置**：使用`http.Server`结构体，便于后续扩展（如TLS支持）。
5. **错误处理**：对无效输入和不支持的HTTP方法返回适当的HTTP状态码。
6. **防止潜在的脚本注入**：通过输入验证和输出限制，避免恶意命令被执行或返回给客户端。

优化后的代码更加安全、稳定，适合在生产环境中使用。

