// bruteForce attempts to guess the target string by generating random combinations
// of characters from the given charset up to a specified maximum length.
func bruteForce(target string, charset string, maxLength int) string {
	// Seed the random number generator with the current time to ensure randomness.
	rand.Seed(time.Now().UnixNano())

	// Iterate over possible lengths of the guessed string, starting from 1 up to maxLength.
	for length := 1; length <= maxLength; length++ {
		// This loop generates guesses indefinitely for the current length.
		// The loop condition uses the maximum value of an int (int(^uint(0)>>1)) as a large number.
		for i := 0; i < int(^uint(0)>>1); i++ {
			var guess []byte // Initialize an empty byte slice to build the guess.

			// Generate a random string of the current length.
			for j := 0; j < length; j++ {
				// Append a random character from the charset to the guess.
				guess = append(guess, charset[rand.Intn(len(charset))])
			}

			// Check if the generated guess matches the target string.
			if string(guess) == target {
				return string(guess) // Return the correct guess if found.
			}
		}
	}

	// Return an empty string if the target is not found within the given constraints.
	return ""
}

func main() {
	// Define the target password to crack.
	target := "password123"

	// Define the character set to use for guessing.
	charset := "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

	// Define the maximum length of the password to attempt.
	maxLength := 12

	// Call the bruteForce function and print the result.
	fmt.Println("Cracking password:", bruteForce(target, charset, maxLength))
}
