)

func fetchProductData(url string) ([]byte, error) {
	// Create an HTTP client with a timeout
	client := &http.Client{
		Timeout: 10 * time.Second, // Set a timeout to prevent hanging requests
	}

	// Send the GET request
	resp, err := client.Get(url)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch data: %w", err)
	}
	defer resp.Body.Close()

	// Check for non-200 HTTP status codes
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("received non-200 response: %d %s", resp.StatusCode, http.StatusText(resp.StatusCode))
	}

	// Read the response body
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %w", err)
	}

	return body, nil
}

func main() {
	url := "https://example.com/api/product"
	data, err := fetchProductData(url)
	if err != nil {
		fmt.Printf("Error fetching product data: %v\n", err)
		return
	}

	fmt.Printf("Product data: %s\n", string(data))
}
