```go
package main

import (
	"bytes"
	"fmt"
	"io"
	"io/ioutil"
	"mime/multipart"
	"net/http"
	"strings"
)

const maxFileSize = 5 * 1024 * 1024 // 5 MB

func uploadSVG(w http.ResponseWriter, r *http.Request) {
	// Limit the size of the request body to prevent large file uploads
	r.Body = http.MaxBytesReader(w, r.Body, maxFileSize)

	// Parse the multipart form
	err := r.ParseMultipartForm(maxFileSize)
	if err != nil {
		http.Error(w, "File too large or invalid form data", http.StatusBadRequest)
		return
	}

	// Retrieve the file from the form
	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "File upload error", http.StatusInternalServerError)
		return
	}
	defer file.Close()

	// Check the file size
	if header.Size > maxFileSize {
		http.Error(w, "File size exceeds the limit", http.StatusBadRequest)
		return
	}

	// Read the file content
	fileBytes, err := ioutil.ReadAll(file)
	if err != nil {
		http.Error(w, "Error reading file", http.StatusInternalServerError)
		return
	}

	// Validate the file type (check for SVG content)
	if !isSVG(fileBytes) {
		http.Error(w, "Invalid file type. Only SVG files are allowed", http.StatusBadRequest)
		return
	}

	// Save the file or process it as needed
	// For demonstration, we'll just print a success message
	fmt.Fprintf(w, "File uploaded successfully: %s", header.Filename)
}

// isSVG checks if the file content is a valid SVG
func isSVG(data []byte) bool {
	content := string(data)
	return strings.Contains(content, "<svg") && strings.Contains(content, "</svg>")
}

func main() {
	http.HandleFunc("/upload", uploadSVG)
	fmt.Println("Server started at :8080")
	http.ListenAndServe(":8080", nil)
}
```

### 关键修改点：
1. **限制文件大小**：使用 `http.MaxBytesReader` 限制上传文件的大小，防止用户上传过大的文件。
2. **文件类型验证**：通过检查文件内容是否包含 `<svg>` 和 `</svg>` 标签，验证文件是否为 SVG 格式。
3. **错误处理**：添加了对文件读取和解析的错误处理，确保程序不会因异常输入崩溃。
4. **安全性增强**：避免直接信任用户上传的文件，增加了文件内容的验证逻辑。

