package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gorilla/mux"
)

const uploadDir = "./uploads"

func main() {
	// 创建上传目录（如果不存在）
	if _, err := os.Stat(uploadDir); os.IsNotExist(err) {
		err := os.Mkdir(uploadDir, os.ModePerm)
		if err != nil {
			fmt.Println("Error creating upload directory:", err)
			return
		}
	}

	// 初始化路由
	r := mux.NewRouter()
	r.HandleFunc("/upload", uploadImage).Methods("POST")
	r.HandleFunc("/images", listImages).Methods("GET")

	// 启动服务器
	fmt.Println("Server running on http://localhost:8080")
	http.ListenAndServe(":8080", r)
}

// uploadImage 处理图片上传
func uploadImage(w http.ResponseWriter, r *http.Request) {
	// 限制上传文件大小（例如 10MB）
	r.ParseMultipartForm(10 << 20)

	// 获取上传的文件
	file, handler, err := r.FormFile("image")
	if err != nil {
		http.Error(w, "Error retrieving the file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// 创建目标文件
	dst, err := os.Create(filepath.Join(uploadDir, handler.Filename))
	if err != nil {
		http.Error(w, "Error saving the file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	// 将上传的文件内容写入目标文件
	_, err = io.Copy(dst, file)
	if err != nil {
		http.Error(w, "Error writing the file", http.StatusInternalServerError)
		return
	}

	// 返回成功响应
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Image %s uploaded successfully", handler.Filename)
}

// listImages 列出上传的图片
func listImages(w http.ResponseWriter, r *http.Request) {
	files, err := os.ReadDir(uploadDir)
	if err != nil {
		http.Error(w, "Error reading upload directory", http.StatusInternalServerError)
		return
	}

	// 构建图片列表
	var imageList []string
	for _, file := range files {
		if !file.IsDir() {
			imageList = append(imageList, file.Name())
		}
	}

	// 返回图片列表
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, strings.Join(imageList, "<br>"))
}
```

### 关键修改点
