以下是一个使用Go语言实现的旅行评价网站的核心功能代码。我们将使用Go的`net/http`包来处理HTTP请求，并使用内存中的数据存储来简化实现。实际生产环境中可以扩展为使用数据库（如PostgreSQL或MongoDB）存储数据。

### 核心功能实现
```go
package main

import (
	"encoding/json"
	"net/http"
	"sync"
)

// Review represents a travel review
type Review struct {
	ID      int    `json:"id"`
	User    string `json:"user"`
	Title   string `json:"title"`
	Content string `json:"content"`
	Rating  int    `json:"rating"` // Rating out of 5
}

var (
	reviews      = []Review{}
	reviewsMutex = &sync.Mutex{}
	nextID       = 1
)

func main() {
	http.HandleFunc("/reviews", handleReviews)
	http.HandleFunc("/reviews/", handleReviewByID)

	http.ListenAndServe(":8080", nil)
}

// handleReviews handles GET and POST requests for reviews
func handleReviews(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		getAllReviews(w, r)
	case http.MethodPost:
		createReview(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// handleReviewByID handles GET requests for a specific review by ID
func handleReviewByID(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	id := r.URL.Path[len("/reviews/"):]
	getReviewByID(w, r, id)
}

// getAllReviews returns all reviews as JSON
func getAllReviews(w http.ResponseWriter, r *http.Request) {
	reviewsMutex.Lock()
	defer reviewsMutex.Unlock()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(reviews)
}

// createReview creates a new review from the request body
func createReview(w http.ResponseWriter, r *http.Request) {
	var newReview Review
	if err := json.NewDecoder(r.Body).Decode(&newReview); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	reviewsMutex.Lock()
	defer reviewsMutex.Unlock()

	newReview.ID = nextID
	nextID++
	reviews = append(reviews, newReview)

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newReview)
}

// getReviewByID returns a specific review by ID
func getReviewByID(w http.ResponseWriter, r *http.Request, id string) {
	reviewsMutex.Lock()
	defer reviewsMutex.Unlock()

	for _, review := range reviews {
		if id == string(rune(review.ID)) {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(review)
			return
		}
	}

	http.Error(w, "Review not found", http.StatusNotFound)
}
```

### 关键修改点说明
1. **线程安全**：使用`sync.Mutex`保护共享的`reviews`切片，避免并发写入导致数据竞争。
2. **路由设计**：
   - `/reviews`：支持`GET`获取所有评论，`POST`创建新评论。
   - `/reviews/{id}`：支持`GET`获取特定ID的评论。
3. **JSON序列化/反序列化**：使用`encoding/json`包处理请求和响应的JSON数据。
4. **ID生成**：通过`nextID`变量为每条评论生成唯一ID。
5. **错误处理**：对无效请求方法和JSON解析错误进行处理，返回适当的HTTP状态码。

### 测试方法
1. 启动服务：运行代码后，服务将在`http://localhost:8080`上监听。
2. 测试获取所有评论：
   ```bash
   curl http://localhost:8080/reviews
   ```
3. 测试创建评论：
   ```bash
   curl -X POST -H "Content-Type: application/json" -d '{"user":"John","title":"Great Trip","content":"Had a wonderful time!","rating":5}' http://localhost:8080/reviews
   ```
4. 测试获取特定评论：
   ```bash
   curl http://localhost:8080/reviews/1
   ```

