以下是一个使用Go语言实现调用API接口的功能代码示例。此代码实现了一个简单的API调用功能，用户可以通过此功能获取房源信息并与经纪人交流。

### 实现思路
1. **定义API调用的结构**：使用`struct`定义请求和响应的结构体。
2. **封装HTTP请求**：使用`net/http`库发送GET或POST请求。
3. **解析API响应**：使用`encoding/json`解析JSON格式的响应数据。
4. **错误处理**：对API调用的错误进行处理，确保程序的健壮性。
5. **优化代码结构**：将API调用封装为函数，便于复用。

### 优化后的代码
```go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"time"
)

// 房源信息结构体
type Property struct {
	ID          int     `json:"id"`
	Title       string  `json:"title"`
	Price       float64 `json:"price"`
	Location    string  `json:"location"`
	Description string  `json:"description"`
}

// API响应结构体
type APIResponse struct {
	Success bool        `json:"success"`
	Data    interface{} `json:"data"`
	Message string      `json:"message"`
}

// 获取房源信息的函数
func fetchProperties(apiURL string) ([]Property, error) {
	client := &http.Client{Timeout: 10 * time.Second}

	// 发送GET请求
	resp, err := client.Get(apiURL)
	if err != nil {
		return nil, fmt.Errorf("failed to fetch properties: %v", err)
	}
	defer resp.Body.Close()

	// 检查HTTP状态码
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// 读取响应体
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("failed to read response body: %v", err)
	}

	// 解析JSON响应
	var apiResp APIResponse
	err = json.Unmarshal(body, &apiResp)
	if err != nil {
		return nil, fmt.Errorf("failed to parse JSON response: %v", err)
	}

	// 检查API响应是否成功
	if !apiResp.Success {
		return nil, fmt.Errorf("API error: %s", apiResp.Message)
	}

	// 将响应数据转换为房源信息列表
	properties := []Property{}
	dataBytes, _ := json.Marshal(apiResp.Data)
	err = json.Unmarshal(dataBytes, &properties)
	if err != nil {
		return nil, fmt.Errorf("failed to parse property data: %v", err)
	}

	return properties, nil
}

// 与经纪人交流的函数
func contactAgent(apiURL string, agentID int, message string) error {
	client := &http.Client{Timeout: 10 * time.Second}

	// 构造POST请求的JSON数据
	requestBody := map[string]interface{}{
		"agent_id": agentID,
		"message":  message,
	}
	jsonData, err := json.Marshal(requestBody)
	if err != nil {
		return fmt.Errorf("failed to marshal request body: %v", err)
	}

	// 发送POST请求
	resp, err := client.Post(apiURL, "application/json", bytes.NewBuffer(jsonData))
	if err != nil {
		return fmt.Errorf("failed to contact agent: %v", err)
	}
	defer resp.Body.Close()

	// 检查HTTP状态码
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// 读取响应体
	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("failed to read response body: %v", err)
	}

	// 解析JSON响应
	var apiResp APIResponse
	err = json.Unmarshal(body, &apiResp)
	if err != nil {
		return fmt.Errorf("failed to parse JSON response: %v", err)
	}

	// 检查API响应是否成功
	if !apiResp.Success {
		return fmt.Errorf("API error: %s", apiResp.Message)
	}

	return nil
}

func main() {
	// 示例：获取房源信息
	apiURL := "https://api.example.com/properties"
	properties, err := fetchProperties(apiURL)
	if err != nil {
		fmt.Printf("Error fetching properties: %v\n", err)
		return
	}
	fmt.Println("Fetched properties:", properties)

	// 示例：联系经纪人
	contactURL := "https://api.example.com/contact-agent"
	err = contactAgent(contactURL, 123, "Hello, I am interested in this property.")
	if err != nil {
		fmt.Printf("Error contacting agent: %v\n", err)
		return
	}
	fmt.Println("Successfully contacted the agent.")
}
```

### 关键修改点
1. **封装API调用逻辑**：将获取房源信息和联系经纪人的逻辑封装为独立函数，便于复用和维护。
2. **增加超时设置**：为HTTP客户端设置超时时间，避免请求长时间挂起。
3. **统一错误处理**：对HTTP状态码、JSON解析和API响应结果进行统一的错误处理。
4. **灵活解析响应数据**：使用`interface{}`和`json.Marshal`/`json.Unmarshal`处理动态数据结构。
5. **代码结构清晰**：主函数调用封装好的函数，逻辑清晰易读。

