        <p>Write your JavaScript code below and click "Run Code" to see the output:</p>
        <textarea id="codeEditor">// Write your JavaScript code here
console.log('Hello, World!');</textarea>
        <button id="runButton">Run Code</button>
        <iframe id="outputFrame"></iframe>
    </div>

    <script>
        // Get references to the DOM elements
        const codeEditor = document.getElementById('codeEditor');
        const runButton = document.getElementById('runButton');
        const outputFrame = document.getElementById('outputFrame');

        // Add event listener to the "Run Code" button
        runButton.addEventListener('click', () => {
            // Get the user's code from the textarea
            const userCode = codeEditor.value;

            // Create a Blob containing the user's code
            const blob = new Blob([`
                <html>
                <body>
                <script>
                try {
                    ${userCode}
                } catch (error) {
                    console.error(error);
                    document.body.innerHTML = '<pre style="color: red;">' + error + '</pre>';
                }
                </script>
                </body>
                </html>
            `], { type: 'text/html' });

            // Create a URL for the Blob and set it as the iframe's source
            const blobURL = URL.createObjectURL(blob);
            outputFrame.src = blobURL;
        });
    </script>
</body>
</html>
