    let map;

    // 初始化地图
    function initMap() {
      map = new google.maps.Map(document.getElementById("map"), {
        center: { lat: 40.7128, lng: -74.0060 }, // 默认中心点：纽约
        zoom: 12,
      });

      // 模拟加载交通数据
      loadTrafficData();
    }

    // 加载交通数据
    function loadTrafficData() {
      // 示例：使用 axios 从外部 API 获取交通数据
      axios.get('https://api.example.com/traffic-data')
        .then(response => {
          const data = response.data;
          document.getElementById('traffic-info').innerText = `Current Traffic: ${data.status}`;
          // 在地图上显示交通数据（示例：标记拥堵区域）
          data.locations.forEach(location => {
            new google.maps.Marker({
              position: { lat: location.lat, lng: location.lng },
              map: map,
              title: location.status,
            });
          });
        })
        .catch(error => {
          console.error('Error loading traffic data:', error);
          document.getElementById('traffic-info').innerText = 'Failed to load traffic data.';
        });
