```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>在线课程平台 - 教师上传JavaScript</title>
</head>
<body>
    <h1>在线课程平台 - 教师上传JavaScript</h1>
    <p>通过上传自定义 JavaScript 文件来增强课程页面的互动性。</p>

    <!-- 文件上传表单 -->
    <form id="uploadForm">
        <label for="jsFile">选择一个 JavaScript 文件：</label>
        <input type="file" id="jsFile" accept=".js">
        <button type="button" id="uploadButton">上传并加载</button>
    </form>

    <div id="output" style="margin-top: 20px; color: red;"></div>

    <script>
        document.getElementById('uploadButton').addEventListener('click', function () {
            const fileInput = document.getElementById('jsFile');
            const output = document.getElementById('output');

            // 清空之前的消息
            output.textContent = '';

            // 检查是否选择了文件
            if (!fileInput.files.length) {
                output.textContent = '请先选择一个 JavaScript 文件。';
                return;
            }

            const file = fileInput.files[0];

            // 检查文件类型
            if (file.type !== 'application/javascript' && !file.name.endsWith('.js')) {
                output.textContent = '仅支持上传 .js 文件。';
                return;
            }

            // 读取文件内容
            const reader = new FileReader();
            reader.onload = function (event) {
                try {
                    // 创建一个新的 script 元素
                    const script = document.createElement('script');
                    script.textContent = event.target.result;

                    // 动态加载脚本到页面
                    document.body.appendChild(script);

                    output.style.color = 'green';
                    output.textContent = 'JavaScript 文件已成功加载！';
                } catch (error) {
                    output.textContent = '加载 JavaScript 文件时出错：' + error.message;
                }
            };

            reader.onerror = function () {
                output.textContent = '无法读取文件，请重试。';
            };

            reader.readAsText(file);
        });
    </script>
</body>
</html>
```

