    <!-- Content Security Policy (CSP) -->
    <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; media-src 'self'; img-src 'self' data:;">

    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 20px;
        }
        #preview-container {
            margin-top: 20px;
        }
