            display: none;
        }
        video {
            max-width: 100%;
            height: auto;
        }
    </style>
</head>
<body>
    <h1>上传媒体并预览</h1>
    <form id="upload-form">
        <label for="media-upload">选择图片或视频文件：</label>
        <input type="file" id="media-upload" accept="image/*,video/*">
    </form>

    <div id="preview-container">
        <p>预览：</p>
        <img id="preview" alt="图片预览">
        <video id="video-preview" controls></video>
    </div>

    <script>
        document.getElementById('media-upload').addEventListener('change', function(event) {
            const file = event.target.files[0];
            const previewImage = document.getElementById('preview');
            const previewVideo = document.getElementById('video-preview');

            // 清空之前的预览
            previewImage.style.display = 'none';
            previewVideo.style.display = 'none';
            previewVideo.src = '';
            previewImage.src = '';

            if (file) {
                const fileType = file.type;

                // 验证文件类型
                if (fileType.startsWith('image/')) {
                    const objectURL = URL.createObjectURL(file);
                    previewImage.src = objectURL;
                    previewImage.style.display = 'block';
                } else if (fileType.startsWith('video/')) {
                    const objectURL = URL.createObjectURL(file);
                    previewVideo.src = objectURL;
                    previewVideo.style.display = 'block';
                } else {
                    alert('仅支持图片或视频文件！');
                }
            }
        });
    </script>
</body>
</html>
```

