### 完整代码示例
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Feedback Filter</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      margin: 20px;
    }
    input {
      width: 100%;
      padding: 10px;
      margin-bottom: 20px;
      font-size: 16px;
    }
    ul {
      list-style-type: none;
      padding: 0;
    }
    li {
      padding: 10px;
      border: 1px solid #ddd;
      margin-bottom: 5px;
      border-radius: 5px;
    }
    .no-results {
      color: #888;
      font-style: italic;
    }
  </style>
</head>
<body>
  <h1>Feedback Filter</h1>
  <input type="text" id="keywordInput" placeholder="Enter keyword to filter feedback..." />

  <ul id="feedbackList">
    <li>Great platform, very user-friendly!</li>
    <li>The customer service was excellent.</li>
    <li>I love the new features in the latest update.</li>
    <li>Could use some improvements in the UI design.</li>
    <li>Overall, a fantastic experience!</li>
  </ul>

  <script>
    // JavaScript to handle filtering
    const input = document.getElementById('keywordInput');
    const feedbackList = document.getElementById('feedbackList');
    const feedbackItems = Array.from(feedbackList.getElementsByTagName('li'));

    input.addEventListener('input', () => {
      const keyword = input.value.toLowerCase();
      let hasResults = false;

      feedbackItems.forEach(item => {
        if (item.textContent.toLowerCase().includes(keyword)) {
          item.style.display = ''; // Show item
          hasResults = true;
        } else {
          item.style.display = 'none'; // Hide item
        }
      });

      // Handle "no results" case
      if (!hasResults) {
        if (!document.querySelector('.no-results')) {
          const noResultsMessage = document.createElement('li');
          noResultsMessage.textContent = 'No matching results found.';
          noResultsMessage.className = 'no-results';
          feedbackList.appendChild(noResultsMessage);
        }
      } else {
        const noResultsMessage = document.querySelector('.no-results');
        if (noResultsMessage) {
          noResultsMessage.remove();
        }
      }
    });
  </script>
</body>
</html>
```

