import java.util.concurrent.ConcurrentHashMap;

public class OnlineCounselingService {

    // 使用线程安全的ConcurrentHashMap存储数据
    private static final Map<Integer, Map<String, String>> counselors = new ConcurrentHashMap<>();
    private static final List<Map<String, Object>> appointments = Collections.synchronizedList(new ArrayList<>());
    private static final List<Map<String, Object>> records = Collections.synchronizedList(new ArrayList<>());

