        this.feedbackText = text;
    }

    public String getFeedbackText() {
        return feedbackText;
    }
}

public class SafeDeserializationExample {
    // 定义允许的类白名单
    private static final Set<Class<?>> ALLOWED_CLASSES = new HashSet<>();

    static {
        ALLOWED_CLASSES.add(FeedbackObject.class); // 仅允许反序列化 FeedbackObject 类
    }

    public static void main(String[] args) {
        try (FileInputStream fileIn = new FileInputStream("feedback.ser");
             ObjectInputStream in = new ObjectInputStream(fileIn) {
                 @Override
                 protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
                     Class<?> clazz = super.resolveClass(desc);
                     if (!ALLOWED_CLASSES.contains(clazz)) {
                         throw new InvalidClassException("Unauthorized deserialization attempt for class: " + clazz.getName());
                     }
                     return clazz;
                 }
             }) {
            FeedbackObject feedback = (FeedbackObject) in.readObject();
            System.out.println("反馈内容: " + feedback.getFeedbackText());
        } catch (InvalidClassException e) {
            System.err.println("安全警告: " + e.getMessage());
        } catch (IOException | ClassNotFoundException e) {
