public class FakeCustomerServiceFraud {
    public static void main(String[] args) {
        HttpURLConnection connection = null;
        Scanner scanner = null;

        try {
            URL url = new URL("https://some_fake_api.com/message");
            connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setDoOutput(true);
            connection.setRequestProperty("Content-Type", "application/json; utf-8");
            connection.setRequestProperty("Accept", "application/json");

            // Use try-with-resources for OutputStream
            String message = "{\"message\": \"Dear customer, your account has issue, click here to fix...\"}";
            try (OutputStream os = connection.getOutputStream()) {
                os.write(message.getBytes("UTF-8"));
                os.flush();
            }

            // Check HTTP response code
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                scanner = new Scanner(connection.getInputStream());
                while (scanner.hasNextLine()) {
                    System.out.println(scanner.nextLine());
                }
            } else {
                System.err.println("HTTP error code: " + responseCode);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            // Ensure resources are closed
            if (scanner != null) {
                scanner.close();
            }
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
}
```

