```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;

public class SecureCommandExecution {
    public static void main(String[] args) {
        try {
            // 定义允许的命令列表
            String allowedCommand = "ls";

            // 模拟用户输入的命令
            String userCommand = "ls -l";

            // 验证用户输入的命令是否合法
            if (!userCommand.startsWith(allowedCommand)) {
                throw new IllegalArgumentException("非法命令输入！");
            }

            // 构建安全的请求
            URL url = new URL("http://servermgmt.example.com/execute_command");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("POST");
            connection.setDoOutput(true);

            // 设置超时
            connection.setConnectTimeout(5000); // 连接超时 5 秒
            connection.setReadTimeout(5000);    // 读取超时 5 秒

            // 对命令进行 URL 编码，防止特殊字符引发问题
            String payload = "command=" + URLEncoder.encode(userCommand, "UTF-8");
            byte[] postData = payload.getBytes();
            connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
            connection.setRequestProperty("Content-Length", Integer.toString(postData.length));

            // 发送请求
            try (OutputStream outputStream = connection.getOutputStream()) {
                outputStream.write(postData);
            }

            // 处理响应
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                    String line;
                    StringBuilder response = new StringBuilder();
                    while ((line = reader.readLine()) != null) {
                        response.append(line);
                    }
                    System.out.println("响应内容: " + response.toString());
                }
            } else {
                System.out.println("请求失败，响应码: " + responseCode);
            }
        } catch (IOException e) {
            System.err.println("网络错误: " + e.getMessage());
        } catch (IllegalArgumentException e) {
            System.err.println("输入错误: " + e.getMessage());
        }
    }
}
```

### 关键修改点说明：
1. **输入验证**：
   - 使用 `allowedCommand` 定义了允许的命令列表，并验证用户输入是否符合预期。
   - 如果用户输入的命令不合法，抛出 `IllegalArgumentException`，防止恶意命令注入。

2. **超时设置**：
   - 使用 `setConnectTimeout` 和 `setReadTimeout` 方法设置了连接超时和读取超时，避免服务器长时间无响应导致程序挂起。

3. **URL 编码**：
   - 使用 `URLEncoder.encode` 对用户输入的命令进行编码，防止特殊字符（如 `&`、`|` 等）被解释为命令注入。

4. **资源管理**：
   - 使用 `try-with-resources` 自动关闭 `OutputStream` 和 `BufferedReader`，避免资源泄漏。

通过这些修改，代码更加安全，能够有效防止命令注入攻击和超时问题。

