            }
        } catch (IOException e) {
            System.out.println("生成简历时发生错误：" + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * 清理文件名中的非法字符
     * @param name 用户输入的姓名
     * @return 合法的文件名
     */
    private static String sanitizeFileName(String name) {
        return name.replaceAll("[\\\\/:*?\"<>|]", "_");
    }
}
```

### 关键修改点
