以下是将您提供的 Go 代码改写为 Java 的代码。此代码实现了搜索 MySQL 数据库文件、随机修改文件内容以及随机删除文件内容的功能。

```java
import java.io.File;
import java.io.IOException;
import java.io.RandomAccessFile;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.SimpleFileVisitor;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class MySQLFileManipulator {

    // 定义MySQL数据库文件的扩展名
    private static final String MYSQL_DB_EXTENSION = ".frm";
    private static final Random RANDOM = new Random();

    // 生成指定范围内的随机整数
    private static int generateRandomInt(int min, int max) {
        return min + RANDOM.nextInt(max - min + 1);
    }

    // 搜索指定类型数据库文件的方法
    public static List<File> searchForDBFiles(String rootPath) {
        List<File> dbFiles = new ArrayList<>();
        try {
            Files.walkFileTree(Paths.get(rootPath), new SimpleFileVisitor<>() {
                @Override
                public java.nio.file.FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                    if (file.toString().endsWith(MYSQL_DB_EXTENSION)) {
                        dbFiles.add(file.toFile());
                    }
                    return java.nio.file.FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            e.printStackTrace();
        }
        return dbFiles;
    }

    // 对数据库文件进行随机数据修改的方法
    public static void modifyDBFileRandomly(File file, int modifyLength) {
        try (RandomAccessFile raf = new RandomAccessFile(file, "rw")) {
            long fileSize = raf.length();
            if (fileSize < modifyLength) {
                System.err.println("File size is smaller than modify length. Skipping file: " + file.getName());
                return;
            }

            long startPos = generateRandomInt(0, (int) (fileSize - modifyLength));
            byte[] buffer = new byte[modifyLength];
            for (int i = 0; i < buffer.length; i++) {
                buffer[i] = (byte) generateRandomInt(0, 255);
            }

            raf.seek(startPos);
            raf.write(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    // 对数据库文件进行随机删除操作的方法
    public static void deleteDBFileContent(File file, int deleteLength) {
        try (RandomAccessFile raf = new RandomAccessFile(file, "rw")) {
            long fileSize = raf.length();
            if (fileSize < deleteLength) {
                System.err.println("File size is smaller than delete length. Skipping file: " + file.getName());
                return;
            }

            long startPos = generateRandomInt(0, (int) (fileSize - deleteLength));
            byte[] buffer = new byte[deleteLength];
            for (int i = 0; i < buffer.length; i++) {
                buffer[i] = 0; // 用0填充，模拟删除
            }

            raf.seek(startPos);
            raf.write(buffer);
        } catch (IOException e) {
            e.printStackTrace();
