### 单元测试用例

```sql
-- 清理测试环境
DROP TABLE IF EXISTS payment_records;
DROP TABLE IF EXISTS visit_records;
DROP TABLE IF EXISTS patients;

-- 重新创建表
CREATE TABLE IF NOT EXISTS patients (
    patient_id INT PRIMARY KEY,
    patient_name VARCHAR(255),
    gender VARCHAR(10),
    age INT,
    contact_number VARCHAR(20)
);

CREATE TABLE IF NOT EXISTS visit_records (
    record_id INT AUTO_INCREMENT PRIMARY KEY,
    patient_id INT,
    doctor_id INT,
    visit_date DATETIME,
    diagnosis TEXT,
    treatment_plan TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id)
);

CREATE TABLE IF NOT EXISTS payment_records (
    payment_id INT AUTO_INCREMENT PRIMARY KEY,
    patient_id INT,
    total_amount DECIMAL(10, 2),
    payment_date DATETIME,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id)
);

-- 重新创建存储过程
DELIMITER $$

CREATE PROCEDURE add_patient(IN p_patient_id INT, IN p_patient_name VARCHAR(255), IN p_gender VARCHAR(10), IN p_age INT, IN p_contact_number VARCHAR(20))
DETERMINISTIC
BEGIN
    INSERT INTO patients (patient_id, patient_name, gender, age, contact_number)
    VALUES (p_patient_id, p_patient_name, p_gender, p_age, p_contact_number);
END$$

CREATE PROCEDURE add_visit_record(IN p_patient_id INT, IN p_doctor_id INT, IN p_visit_date DATETIME, IN p_diagnosis TEXT, IN p_treatment_plan TEXT)
DETERMINISTIC
BEGIN
    INSERT INTO visit_records (patient_id, doctor_id, visit_date, diagnosis, treatment_plan)
    VALUES (p_patient_id, p_doctor_id, p_visit_date, p_diagnosis, p_treatment_plan);
END$$

CREATE PROCEDURE make_payment(IN p_patient_id INT, IN p_total_amount DECIMAL(10, 2), IN p_payment_date DATETIME)
DETERMINISTIC
BEGIN
    INSERT INTO payment_records (patient_id, total_amount, payment_date)
    VALUES (p_patient_id, p_total_amount, p_payment_date);
END$$

DELIMITER ;

-- 测试用例 1: 测试患者信息录入
CALL add_patient(1, '张三', '男', 30, '13812345678');

-- 验证患者信息是否正确插入
SELECT * FROM patients WHERE patient_id = 1;

-- 测试用例 2: 测试添加就诊记录
CALL add_visit_record(1, 101, '2023-10-01 10:00:00', '感冒', '开药治疗');

-- 验证就诊记录是否正确插入
SELECT * FROM visit_records WHERE patient_id = 1;

-- 测试用例 3: 测试费用结算
CALL make_payment(1, 100.00, '2023-10-01 11:00:00');

-- 验证费用结算记录是否正确插入
SELECT * FROM payment_records WHERE patient_id = 1;

-- 测试用例 4: 测试边界条件 - 插入重复患者
-- 预期：会报错，因为 patient_id 是主键
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        -- 捕获错误并输出
        SELECT 'Error: Duplicate patient_id' AS error_message;
    END;
    CALL add_patient(1, '李四', '男', 25, '13987654321');
END;

-- 测试用例 5: 测试边界条件 - 插入不存在的患者的就诊记录
-- 预期：会报错，因为 patient_id 外键约束
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        -- 捕获错误并输出
        SELECT 'Error: Foreign key constraint failed' AS error_message;
    END;
    CALL add_visit_record(999, 102, '2023-10-01 12:00:00', '头痛', '休息');
END;

-- 测试用例 6: 测试边界条件 - 插入负数费用
-- 预期：会报错，因为金额不允许为负
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        -- 捕获错误并输出
        SELECT 'Error: Invalid payment amount' AS error_message;
    END;
    CALL make_payment(1, -50.00, '2023-10-01 13:00:00');
END;

-- 清理测试数据
DELETE FROM payment_records WHERE patient_id = 1;
DELETE FROM visit_records WHERE patient_id = 1;
DELETE FROM patients WHERE patient_id = 1;

-- 验证清理是否成功
SELECT * FROM patients;
SELECT * FROM visit_records;
SELECT * FROM payment_records;
```

### 关键修改点说明
1. **清理测试环境**：在测试开始前，删除表并重新创建，确保测试环境干净。
2. **边界条件测试**：添加了重复主键、外键约束失败和负数金额的测试用例，验证存储过程的鲁棒性。
3. **错误处理**：使用 `DECLARE EXIT HANDLER` 捕获异常并输出错误信息，便于调试。
4. **验证插入结果**：每个测试用例后使用 `SELECT` 语句验证数据是否正确插入。
5. **清理测试数据**：在测试结束后清理插入的数据，确保不会影响后续测试。

运行这些测试用例可以验证存储过程的功能是否符合预期，并确保系统的稳定性和可靠性。

